<script setup>
import { onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import BillView from './BillView.vue'
import { getCommunities } from '../../api/community.js'
import { getFeeStandards, getOverdueBills, getOverdueOverview, getPayments } from '../../api/fee.js'
import { apiMessage } from '../../api/http.js'
import PaginationBar from '../../components/common/PaginationBar.vue'
const activeTab = ref('bills'), communities = ref([]), loading = ref(false), standards = ref([]), payments = ref([]), overdue = ref({ topProperties: [] }), overdueRows = ref([]), standardTotal = ref(0), paymentTotal = ref(0), overdueTotal = ref(0)
const standardQuery = reactive({ communityId: null, status: '', page: 1, pageSize: 20 }), paymentQuery = reactive({ communityId: null, status: '', paymentMethod: '', year: 2026, month: null, page: 1, pageSize: 20 }), overdueQuery = reactive({ communityId: null, year: 2026, month: null, page: 1, pageSize: 20 })
const money = value => new Intl.NumberFormat('zh-CN', { minimumFractionDigits: 2 }).format(value || 0)
async function loadStandards() { loading.value = true; try { const r = await getFeeStandards(standardQuery); standards.value = r.records; standardTotal.value = r.total } catch (e) { ElMessage.error(apiMessage(e, '收费标准加载失败')) } finally { loading.value = false } }
async function loadPayments() { loading.value = true; try { const r = await getPayments(paymentQuery); payments.value = r.records; paymentTotal.value = r.total } catch (e) { ElMessage.error(apiMessage(e, '缴费记录加载失败')) } finally { loading.value = false } }
async function loadOverdue() { loading.value = true; try { const [overview, page] = await Promise.all([getOverdueOverview(overdueQuery), getOverdueBills(overdueQuery)]); overdue.value = overview; overdueRows.value = page.records; overdueTotal.value = page.total } catch (e) { ElMessage.error(apiMessage(e, '欠费管理加载失败')) } finally { loading.value = false } }
function onTab() { if (activeTab.value === 'standards') loadStandards(); if (activeTab.value === 'payments') loadPayments(); if (activeTab.value === 'overdue') loadOverdue() }
function reloadStandards(){loadStandards()} function reloadPayments(){loadPayments()} function reloadOverdue(){loadOverdue()}
onMounted(async () => { try { communities.value = await getCommunities() } catch (e) { ElMessage.error(apiMessage(e)) } })
 </script>
<template><section class="panel center"><el-tabs v-model="activeTab" @tab-change="onTab"><el-tab-pane label="账单管理" name="bills"><BillView/></el-tab-pane><el-tab-pane label="收费标准" name="standards"><div class="filters"><el-select v-model="standardQuery.communityId" clearable placeholder="全部小区"><el-option v-for="c in communities" :key="c.communityId" :label="c.communityName" :value="c.communityId"/></el-select><el-select v-model="standardQuery.status" clearable placeholder="状态"><el-option label="有效" value="ACTIVE"/><el-option label="停用" value="INACTIVE"/></el-select><el-button type="primary" @click="standardQuery.page=1;loadStandards()">查询</el-button></div><el-table v-loading="loading" :data="standards" height="calc(100vh - 365px)"><el-table-column prop="communityName" label="小区"/><el-table-column prop="feeName" label="收费项目"/><el-table-column prop="billingMethod" label="计费方式"/><el-table-column label="单价"><template #default="{row}">¥ {{ money(row.unitPrice) }}</template></el-table-column><el-table-column prop="unitName" label="单位"/><el-table-column prop="effectiveFrom" label="生效日期"/><el-table-column prop="effectiveTo" label="截止日期"><template #default="{row}">{{row.effectiveTo||'长期有效'}}</template></el-table-column><el-table-column prop="status" label="状态"/></el-table><PaginationBar v-model:page="standardQuery.page" v-model:page-size="standardQuery.pageSize" :total="standardTotal" @change="reloadStandards"/></el-tab-pane><el-tab-pane label="缴费记录" name="payments"><div class="filters"><el-select v-model="paymentQuery.communityId" clearable placeholder="全部小区"><el-option v-for="c in communities" :key="c.communityId" :label="c.communityName" :value="c.communityId"/></el-select><el-select v-model="paymentQuery.status" clearable placeholder="支付状态"><el-option label="成功" value="SUCCESS"/></el-select><el-input v-model="paymentQuery.paymentMethod" clearable placeholder="支付方式"/><el-button type="primary" @click="paymentQuery.page=1;loadPayments()">查询</el-button></div><el-table v-loading="loading" :data="payments" height="calc(100vh - 365px)"><el-table-column prop="paymentNo" label="支付单号" min-width="160"/><el-table-column prop="billNo" label="账单号" min-width="150"/><el-table-column prop="communityName" label="小区"/><el-table-column prop="fullLocation" label="完整房产位置" min-width="220"/><el-table-column prop="payerName" label="付款人"/><el-table-column label="金额"><template #default="{row}">¥ {{money(row.amount)}}</template></el-table-column><el-table-column prop="paidAt" label="支付时间" min-width="165"/><el-table-column prop="paymentMethod" label="方式"/><el-table-column prop="status" label="状态"/></el-table><PaginationBar v-model:page="paymentQuery.page" v-model:page-size="paymentQuery.pageSize" :total="paymentTotal" @change="reloadPayments"/></el-tab-pane><el-tab-pane label="欠费管理" name="overdue"><div class="filters"><el-select v-model="overdueQuery.communityId" clearable placeholder="全部小区"><el-option v-for="c in communities" :key="c.communityId" :label="c.communityName" :value="c.communityId"/></el-select><el-button type="primary" @click="overdueQuery.page=1;loadOverdue()">查询</el-button></div><div class="overdue-kpis"><article><span>欠费总额</span><b>¥ {{money(overdue.outstandingAmount)}}</b></article><article><span>欠费户数</span><b>{{overdue.overduePropertyCount||0}}</b></article><article><span>逾期账单数</span><b>{{overdue.overdueBillCount||0}}</b></article></div><h3>Top 欠费房产</h3><el-table :data="overdue.topProperties" max-height="200"><el-table-column prop="fullLocation" label="完整房产位置"/><el-table-column label="欠费"><template #default="{row}">¥ {{money(row.outstandingAmount)}}</template></el-table-column><el-table-column prop="overdueBillCount" label="逾期账单数"/></el-table><h3>欠费列表</h3><el-table v-loading="loading" :data="overdueRows" height="calc(100vh - 540px)"><el-table-column prop="billNo" label="账单号"/><el-table-column prop="fullLocation" label="完整房产位置" min-width="240"/><el-table-column label="账期"><template #default="{row}">{{row.billingYear}}-{{String(row.billingMonth).padStart(2,'0')}}</template></el-table-column><el-table-column label="应收"><template #default="{row}">¥ {{money(row.receivableAmount)}}</template></el-table-column><el-table-column label="实收"><template #default="{row}">¥ {{money(row.receivedAmount)}}</template></el-table-column><el-table-column label="欠费"><template #default="{row}">¥ {{money(row.outstandingAmount)}}</template></el-table-column><el-table-column prop="dueDate" label="截止日"/></el-table><PaginationBar v-model:page="overdueQuery.page" v-model:page-size="overdueQuery.pageSize" :total="overdueTotal" @change="reloadOverdue"/></el-tab-pane></el-tabs></section></template>
<style scoped>.center{padding:20px}.filters{display:flex;gap:10px;margin-bottom:16px}.filters .el-select,.filters .el-input{width:210px}.overdue-kpis{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-bottom:18px}.overdue-kpis article{padding:16px;border:1px solid #e2ebec;border-radius:10px;background:#f7faf9}.overdue-kpis span,.overdue-kpis b{display:block}.overdue-kpis span{color:#718692;font-size:12px}.overdue-kpis b{margin-top:8px;color:#173c4b;font-size:21px}h3{margin:20px 0 10px;font-size:15px}</style>
